const express = require('express');
const router = express.Router();
const { generateAuthenticationOptions } = require('@simplewebauthn/server');

router.post('/auth/passkey/login-options', rateLimiter, async (req, res) => {
  const { email } = req.body;
  const user = email ? await UserModel.findOne({ email }) : null;

  const userCredentials = user ? await CredentialModel.find({ userId: user._id }) : [];
  const options = await generateAuthenticationOptions({
    rpID: 'login.corp.net',
    allowCredentials: userCredentials.slice(0, 5).map(cred => ({
      id: cred.credentialId,
      type: 'public-key',
      transports: cred.transports
    }))
  });

  await ChallengeCache.set(options.challenge, user ? user._id : 'anonymous', 120);
  res.json({ options });
});
